    if options.frmt == nil {
      setFrmt()
    }
    try options.frmt!.doOptions(&options)

    if case .failed = gen_init() {
      exit(exit_val)
    }
    return options
  }

  func runCommand() async throws(CmdErr) {

    let ao = ArchiveOps()
    /*
     * select a primary operation mode
     */
    switch options.act {
      case .EXTRACT:
        ao.extract()
      case .ARCHIVE:
        ao.archive()
      case .APPND:
        if let _ = options.gzip_program {
          errx(1, "can not gzip while appending")
        }
        ao.append()
      case .COPY:
        ao.copy()
      case .LIST:
        ao.list()
      default:
        ao.list()
    }

//    if exit_val == 0 && (ferror(stdout) != 0 || fflush(stdout) != 0) {
//      err(1, "stdout");
